/*!
 * SPARKTECH CMS — live editor.
 *
 * Hover any element marked with data-cms-edit → blue outline + ✎ button.
 * ✎ opens the side panel with the fields declared by the element. Saving
 * writes a draft through admin/api.php; "Publish" makes drafts live.
 *
 * Markup contract (generated by app/lib/doc.php):
 *   data-cms-edit='{"d":doc,"n":name,"f":[{"p":path,"t":type,"l":label,"o":options}]}'
 *   data-cms-b="doc|path|mode"        live-bound output (text | ml | html | img)
 *   data-cms-list="doc|path"          list container   data-cms-item="index"  list item
 *   data-cms-section="doc|key|label"  section (hide / show)   data-cms-off  hidden item/section
 */
(function () {
  'use strict';

  var dataEl = document.getElementById('cms-data');
  if (!dataEl) return;
  var CFG = JSON.parse(dataEl.textContent);
  var DOCS = CFG.docs || {};
  var LIVE_TYPES = { text: 1, textarea: 1, rich: 1, image: 1, video: 1, html: 1, css: 1 };

  // ---------------------------------------------------------------- utilities
  function h(tag, attrs, children) {
    var el = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        var v = attrs[k];
        if (v === null || v === undefined || v === false) return;
        if (k === 'class') el.className = v;
        else if (k === 'html') el.innerHTML = v;
        else if (k === 'text') el.textContent = v;
        else if (k.slice(0, 2) === 'on') el.addEventListener(k.slice(2), v);
        else el.setAttribute(k, v === true ? '' : v);
      });
    }
    (children || []).forEach(function (c) {
      if (c === null || c === undefined || c === false) return;
      el.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
    });
    return el;
  }
  function getPath(obj, path) {
    var cur = obj;
    var segs = path.split('.');
    for (var i = 0; i < segs.length; i++) {
      if (cur === null || cur === undefined) return undefined;
      cur = cur[segs[i]];
    }
    return cur;
  }
  function setPath(obj, path, value) {
    var segs = path.split('.');
    var cur = obj;
    for (var i = 0; i < segs.length - 1; i++) {
      if (cur[segs[i]] === undefined || cur[segs[i]] === null || typeof cur[segs[i]] !== 'object') cur[segs[i]] = /^\d+$/.test(segs[i + 1]) ? [] : {};
      cur = cur[segs[i]];
    }
    cur[segs[segs.length - 1]] = value;
  }
  function resolveUrl(u) {
    u = u || '';
    return u.charAt(0) === '/' && u.charAt(1) !== '/' ? CFG.base + u : u;
  }
  function esc(s) {
    return String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function scopeCss(css, scope) {
    var global = '', scoped = '', i = 0, n = css.length;
    while (i < n) {
      var start = i, depth = 0;
      while (i < n) {
        var ch = css.charAt(i);
        if (ch === '{') depth++;
        else if (ch === '}') { depth--; if (depth <= 0) { i++; break; } }
        else if (ch === ';' && depth === 0) { i++; break; }
        i++;
      }
      var stmt = css.slice(start, i);
      if (/^\s*@(-webkit-)?(keyframes|font-face|import|property|charset)\b/i.test(stmt)) global += stmt.trim() + '\n';
      else scoped += stmt;
    }
    return global + (scoped.trim() ? scope + '{' + scoped + '}' : '');
  }
  function niceName(name) {
    name = String(name || '').replace(/\.[a-z0-9]+$/i, '').replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim();
    return name.charAt(0).toUpperCase() + name.slice(1);
  }
  function imgVal(v) {
    if (v && typeof v === 'object') return { src: v.src || '', alt: v.alt || '' };
    return { src: v || '', alt: '' };
  }
  function attrSel(name, value) {
    return '[' + name + '="' + (window.CSS && CSS.escape ? CSS.escape(value) : value.replace(/"/g, '\\"')) + '"]';
  }
  var ICON_PENCIL = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 013 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>';
  var ICON = {
    up: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M15 18l-6-6 6-6"/></svg>',
    down: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg>',
    dup: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>',
    del: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4a2 2 0 012-2h4a2 2 0 012 2v2m3 0v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6"/></svg>',
    photos: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>',
    youtube: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="4"/><path d="M10 9.5v5l4.5-2.5z" fill="currentColor"/></svg>',
    eye: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>',
    eyeOff: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19M1 1l22 22"/></svg>'
  };

  // -------------------------------------------------------------- API + toasts
  var toasts = h('div', { class: 'cms-toasts', 'aria-live': 'polite' });
  document.body.appendChild(toasts);
  function toast(msg, kind) {
    var t = h('div', { class: 'cms-toast' + (kind ? ' is-' + kind : ''), text: msg });
    toasts.appendChild(t);
    setTimeout(function () { t.remove(); }, kind === 'error' ? 6000 : 2800);
  }
  function api(action, body) {
    var opts = { method: 'POST', credentials: 'same-origin', headers: { 'X-CSRF-Token': CFG.csrf, Accept: 'application/json' } };
    if (body instanceof FormData) opts.body = body;
    else { opts.headers['Content-Type'] = 'application/json'; opts.body = JSON.stringify(body || {}); }
    return fetch(CFG.api + '?action=' + encodeURIComponent(action), opts).then(function (r) {
      return r.json().catch(function () { return { ok: false, error: 'Server error (' + r.status + ')' }; });
    }).then(function (res) {
      if (!res.ok) throw new Error(res.error || 'Request failed');
      if (typeof res.pending === 'number') setPending(res.pending);
      return res;
    });
  }
  function fmtBytes(n) {
    n = +n || 0;
    return n >= 1048576 ? (n / 1048576).toFixed(1) + ' MB' : n >= 1024 ? Math.round(n / 1024) + ' KB' : n + ' B';
  }
  function uploadSummary(f) {
    if (!f || !f.converted || !f.original_size) return 'Uploaded ' + ((f && f.name) || 'file');
    var pct = Math.round(100 - (f.size / f.original_size) * 100);
    return 'Uploaded → WebP · ' + fmtBytes(f.original_size) + ' → ' + fmtBytes(f.size) + (pct > 0 ? ' (−' + pct + '%)' : '');
  }
  function upload(file, onProgress) {
    return new Promise(function (resolve, reject) {
      var fd = new FormData();
      fd.append('file', file);
      var xhr = new XMLHttpRequest();
      xhr.open('POST', CFG.api + '?action=upload');
      xhr.setRequestHeader('X-CSRF-Token', CFG.csrf);
      xhr.setRequestHeader('Accept', 'application/json');
      xhr.upload.onprogress = function (e) { if (e.lengthComputable && onProgress) onProgress(e.loaded / e.total); };
      xhr.onload = function () {
        var res;
        try { res = JSON.parse(xhr.responseText); } catch (e) { res = { ok: false, error: xhr.status === 413 ? 'File is too large for the server.' : 'Upload failed (' + xhr.status + ')' }; }
        if (res.ok) { mediaCache = null; resolve(res.file); } else reject(new Error(res.error || 'Upload failed'));
      };
      xhr.onerror = function () { reject(new Error('Network error during upload')); };
      xhr.send(fd);
    });
  }

  // ------------------------------------------------------------ admin toolbar
  var bar = document.getElementById('cms-adminbar');
  function setPending(n) {
    CFG.pending = n;
    if (!bar) return;
    var b = bar.querySelector('[data-cms-pending]');
    if (b) { b.textContent = n; b.hidden = !n; }
    bar.querySelectorAll('[data-cms-action="publish"],[data-cms-action="discard"]').forEach(function (btn) { btn.disabled = !n; });
  }
  function reloadKeepingScroll() {
    try { sessionStorage.setItem('cms-scroll', JSON.stringify({ p: location.pathname, y: window.scrollY })); } catch (e) {}
    location.reload();
  }
  (function restoreScroll() {
    try {
      var s = JSON.parse(sessionStorage.getItem('cms-scroll') || 'null');
      sessionStorage.removeItem('cms-scroll');
      if (s && s.p === location.pathname) {
        var go = function () { window.scrollTo(0, s.y); };
        go();
        window.addEventListener('load', go);
        setTimeout(go, 400);
      }
    } catch (e) {}
  })();

  function confirmBox(title, text, okLabel, danger) {
    return new Promise(function (resolve) {
      var close = function (v) { m.remove(); resolve(v); };
      var m = h('div', { class: 'cms-modal', role: 'dialog', 'aria-modal': 'true', onclick: function (e) { if (e.target === m) close(false); } }, [
        h('div', { class: 'cms-modal-box is-small' }, [
          h('div', { class: 'cms-modal-head' }, [h('h3', { text: title })]),
          h('div', { class: 'cms-confirm-body', text: text }),
          h('div', { class: 'cms-confirm-foot' }, [
            h('button', { class: 'cms-btn', type: 'button', text: 'Cancel', onclick: function () { close(false); } }),
            h('button', { class: 'cms-btn ' + (danger ? 'cms-btn-danger' : 'cms-btn-primary'), type: 'button', text: okLabel || 'OK', onclick: function () { close(true); } })
          ])
        ])
      ]);
      document.body.appendChild(m);
      m.querySelector('.cms-btn-primary, .cms-btn-danger').focus();
    });
  }

  if (bar) {
    bar.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-cms-action]');
      if (!btn || btn.disabled) return;
      var act = btn.getAttribute('data-cms-action');
      if (act === 'publish') {
        confirmBox('Publish changes?', 'All draft changes (' + CFG.pending + ' page' + (CFG.pending === 1 ? '' : 's') + ') will become visible to every visitor.', 'Publish now').then(function (ok) {
          if (!ok) return;
          btn.disabled = true;
          api('publish', {}).then(function () { toast('Published — your changes are live!', 'ok'); setTimeout(reloadKeepingScroll, 700); })
            .catch(function (err) { btn.disabled = false; toast(err.message, 'error'); });
        });
      } else if (act === 'discard') {
        confirmBox('Discard all drafts?', 'Every unpublished change will be thrown away and the pages go back to the live version. This cannot be undone.', 'Discard changes', true).then(function (ok) {
          if (!ok) return;
          api('discard', {}).then(function () { toast('Changes discarded'); setTimeout(reloadKeepingScroll, 500); })
            .catch(function (err) { toast(err.message, 'error'); });
        });
      } else if (act === 'seo') {
        openSeoPanel();
      } else if (act === 'pages') {
        openPagesMenu();
      }
    });
  }

  function openPagesMenu() {
    var close = function () { m.remove(); };
    var list = h('ul', { class: 'cms-pages' }, (CFG.pages || []).map(function (p) {
      return h('li', null, [h('a', { href: resolveUrl(p[0]), class: p[0] === CFG.page.path ? 'is-current' : '', text: p[1] })]);
    }));
    var m = h('div', { class: 'cms-modal', onclick: function (e) { if (e.target === m) close(); } }, [
      h('div', { class: 'cms-modal-box is-small' }, [
        h('div', { class: 'cms-modal-head' }, [h('h3', { text: 'Edit another page' }), h('button', { class: 'cms-x', type: 'button', 'aria-label': 'Close', text: '×', onclick: close })]),
        list,
        h('div', { class: 'cms-confirm-foot' }, [
          h('a', { class: 'cms-btn', href: CFG.admin + 'popups.php', text: 'Popups…' }),
          h('a', { class: 'cms-btn', href: CFG.admin + 'pages.php', text: 'Manage pages & services…' })
        ])
      ])
    ]);
    document.body.appendChild(m);
  }

  // ---------------------------------------------------------------- overlay
  var ui = h('div', { id: 'cms-ui' });
  var outline = h('div', { class: 'cms-outline' });
  var itemOutline = h('div', { class: 'cms-outline is-item' });
  var tag = h('div', { class: 'cms-tag' });
  var pencil = h('button', { class: 'cms-pencil', type: 'button', title: 'Edit', 'aria-label': 'Edit', html: ICON_PENCIL });
  var itemBar = h('div', { class: 'cms-bar' });
  var sectionBar = h('div', { class: 'cms-bar is-section' });
  var addBtn = h('button', { class: 'cms-addbtn', type: 'button', text: '+ Add item' });
  [itemOutline, outline, tag, pencil, itemBar, sectionBar, addBtn].forEach(function (n) { ui.appendChild(n); });
  document.body.appendChild(ui);

  var hover = { edit: null, item: null, section: null, emptyList: null };
  var mouse = { x: -1, y: -1 };
  var pending = false;
  var overUi = false;
  var switchTimer = 0;
  var HOVER_DELAY = 450;

  function specOf(el) {
    if (!el.__cmsSpec) {
      try { el.__cmsSpec = JSON.parse(el.getAttribute('data-cms-edit')); } catch (e) { el.__cmsSpec = null; }
    }
    return el.__cmsSpec;
  }
  function specName(spec) {
    if (!spec) return '';
    if (spec.n) return spec.n;
    var f = spec.f && spec.f[0];
    if (!f) return 'Edit';
    return f.l || (f.t === 'image' ? 'Image' : f.t === 'rich' ? 'Rich text' : 'Text');
  }
  function visibleRect(el) {
    var r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0 ? r : null;
  }

  function pick() {
    pending = false;
    if (overUi || panel.open && panel.el && mouse.x > window.innerWidth - panel.el.offsetWidth) return;
    var stack = document.elementsFromPoint(mouse.x, mouse.y);
    if (!stack.length) return;
    if (stack[0].closest && stack[0].closest('#cms-ui, .cms-panel, .cms-modal, #cms-adminbar, .cms-tip')) return;
    // An open popup / photo viewer covers the page: only target things inside it.
    var layer = stack[0].closest && stack[0].closest('.st-popup, .st-lb, [data-lightbox]');
    if (layer) stack = stack.filter(function (n) { return layer.contains(n); });

    // Topmost editable / list item under the pointer (overlays that are not
    // editable themselves are skipped, so images below gradients stay reachable).
    var best = null, bestItem = null;
    for (var i = 0; i < stack.length && (!best || !bestItem); i++) {
      var node = stack[i];
      if (!node.closest) continue;
      if (!best) {
        var ed = node.closest('[data-cms-edit]');
        if (ed && visibleRect(ed)) best = ed;
      }
      if (!bestItem) {
        var it = node.closest('[data-cms-item]');
        if (it && visibleRect(it)) bestItem = it;
      }
    }
    var section = stack[0].closest && stack[0].closest('[data-cms-section]');
    var emptyList = null;
    if (!bestItem) {
      stack.some(function (node) {
        var l = node.closest && node.closest('[data-cms-list]');
        if (l && !l.querySelector('[data-cms-item]')) { emptyList = l; return true; }
        return false;
      });
    }
    applyHover({ edit: best, item: bestItem, section: section, emptyList: emptyList });
  }

  // Hover intent: while the pointer is still close to the current outline, ✎ or
  // toolbar, a different target only takes over once the pointer rests on it.
  // Moving toward the pencil across nested elements no longer makes it vanish.
  function sameHover(a, b) {
    return a.edit === b.edit && a.item === b.item && a.section === b.section && a.emptyList === b.emptyList;
  }
  function nearUi() {
    var pad = 24;
    return [outline, itemOutline, pencil, itemBar, addBtn].some(function (n) {
      if (!n.style.display || n.style.display === 'none') return false;
      var r = n.getBoundingClientRect();
      return mouse.x >= r.left - pad && mouse.x <= r.right + pad && mouse.y >= r.top - pad && mouse.y <= r.bottom + pad;
    });
  }
  function applyHover(next) {
    clearTimeout(switchTimer);
    if (sameHover(next, hover) || !nearUi()) { hover = next; place(); return; }
    place();
    switchTimer = setTimeout(function () { hover = next; place(); }, HOVER_DELAY);
  }

  function clampTop(y) { return Math.max(y, 6); }

  function place() {
    var vw = window.innerWidth;
    // editable outline + pencil
    if (hover.edit && document.contains(hover.edit)) {
      var r = hover.edit.getBoundingClientRect();
      Object.assign(outline.style, { display: 'block', top: r.top - 3 + 'px', left: r.left - 3 + 'px', width: r.width + 6 + 'px', height: r.height + 6 + 'px' });
      tag.textContent = '✎ ' + specName(specOf(hover.edit));
      Object.assign(tag.style, { display: 'block', top: clampTop(r.top - 24) + 'px', left: Math.max(4, r.left - 3) + 'px' });
      var px = Math.min(vw - 44, Math.max(6, r.right - 17));
      var py = clampTop(r.top - 17);
      Object.assign(pencil.style, { display: 'flex', top: py + 'px', left: px + 'px' });
    } else {
      outline.style.display = tag.style.display = pencil.style.display = 'none';
    }
    // list item toolbar
    if (hover.item && document.contains(hover.item)) {
      var list = hover.item.parentElement.closest('[data-cms-list]');
      if (list) {
        var ri = hover.item.getBoundingClientRect();
        Object.assign(itemOutline.style, { display: 'block', top: ri.top - 2 + 'px', left: ri.left - 2 + 'px', width: ri.width + 4 + 'px', height: ri.height + 4 + 'px' });
        buildItemBar(list, hover.item);
        itemBar.style.display = 'flex';
        var bx = Math.max(4, Math.min(vw - itemBar.offsetWidth - 4, ri.left));
        var by = ri.bottom + 4 + 30 > window.innerHeight ? ri.bottom - 34 : ri.bottom + 4;
        Object.assign(itemBar.style, { display: 'flex', top: by + 'px', left: bx + 'px' });
      }
    } else {
      itemOutline.style.display = itemBar.style.display = 'none';
    }
    // empty list "add" button
    if (hover.emptyList) {
      var rl = hover.emptyList.getBoundingClientRect();
      addBtn.__list = hover.emptyList;
      Object.assign(addBtn.style, { display: 'flex', top: clampTop(rl.top) + 'px', left: rl.left + 'px' });
    } else {
      addBtn.style.display = 'none';
    }
    // section toolbar
    if (hover.section && document.contains(hover.section)) {
      buildSectionBar(hover.section);
      sectionBar.style.display = 'flex';
      var rs = hover.section.getBoundingClientRect();
      var headerH = 96;
      var sy = Math.max(rs.top + 10, headerH);
      if (sy > rs.bottom - 40) sy = rs.bottom - 40;
      Object.assign(sectionBar.style, { display: 'flex', top: sy + 'px', left: Math.max(4, rs.right - sectionBar.offsetWidth - 14) + 'px' });
    } else {
      sectionBar.style.display = 'none';
    }
  }

  function buildItemBar(list, item) {
    if (itemBar.__item === item) return;
    itemBar.__item = item;
    var parts = list.getAttribute('data-cms-list').split('|');
    var label = list.getAttribute('data-cms-list-label') || 'item';
    var index = parseInt(item.getAttribute('data-cms-item'), 10);
    var siblings = Array.prototype.filter.call(list.querySelectorAll('[data-cms-item]'), function (el) { return el.parentElement.closest('[data-cms-list]') === list; });
    var pos = siblings.indexOf(item);
    itemBar.innerHTML = '';
    var op = function (name, title, html, cls) {
      return h('button', { type: 'button', title: title, 'aria-label': title, class: cls || '', html: html, onclick: function (e) {
        e.preventDefault(); e.stopPropagation(); listOp(parts[0], parts[1], name, index, label);
      } });
    };
    itemBar.appendChild(h('span', { text: label.charAt(0).toUpperCase() + label.slice(1) + ' ' + (pos + 1) }));
    if (pos > 0) itemBar.appendChild(op('up', 'Move earlier', ICON.up));
    if (pos < siblings.length - 1) itemBar.appendChild(op('down', 'Move later', ICON.down));
    itemBar.appendChild(op('dup', 'Duplicate (add a copy after this one)', ICON.dup + ' Copy'));
    if (list.hasAttribute('data-cms-list-photo')) {
      itemBar.appendChild(h('button', { type: 'button', title: 'Upload several photos — each becomes a new ' + label, html: ICON.photos + ' Photos', onclick: function (e) {
        e.preventDefault(); e.stopPropagation(); addPhotos(list, itemGroup(list, index));
      } }));
    }
    if (list.hasAttribute('data-cms-list-youtube')) {
      itemBar.appendChild(h('button', { type: 'button', title: 'Add a YouTube video — it becomes a new ' + label + ' that plays in a pop-up', html: ICON.youtube + ' YouTube', onclick: function (e) {
        e.preventDefault(); e.stopPropagation(); addYoutube(list, itemGroup(list, index));
      } }));
    }
    itemBar.appendChild(op('del', 'Delete this ' + label, ICON.del, 'is-danger'));
  }

  function buildSectionBar(section) {
    if (sectionBar.__section === section) return;
    sectionBar.__section = section;
    var p = section.getAttribute('data-cms-section').split('|');
    var hidden = section.hasAttribute('data-cms-off');
    sectionBar.innerHTML = '';
    sectionBar.appendChild(h('span', { text: 'Section: ' + p[2] + (hidden ? ' (hidden)' : '') }));
    sectionBar.appendChild(h('button', { type: 'button', html: (hidden ? ICON.eye + ' Show' : ICON.eyeOff + ' Hide'), title: hidden ? 'Show this section to visitors' : 'Hide this section from visitors', onclick: function (e) {
      e.preventDefault();
      api('section', { doc: p[0], key: p[1], hidden: !hidden }).then(function () {
        toast(hidden ? 'Section will be shown (after Publish)' : 'Section hidden (after Publish)');
        setTimeout(reloadKeepingScroll, 400);
      }).catch(function (err) { toast(err.message, 'error'); });
    } }));
  }

  function listOp(doc, path, op, index, label) {
    var go = function () {
      api('list', { doc: doc, path: path, op: op, index: index }).then(function () {
        toast(op === 'del' ? 'Deleted' : op === 'dup' || op === 'add' ? 'Copy added — edit it now' : 'Moved');
        setTimeout(reloadKeepingScroll, 300);
      }).catch(function (err) { toast(err.message, 'error'); });
    };
    if (op === 'del') {
      confirmBox('Delete this ' + label + '?', 'It is removed from the draft. You can still Discard before publishing, or restore an older version from History.', 'Delete', true)
        .then(function (ok) { if (ok) go(); });
    } else go();
  }

  addBtn.addEventListener('click', function () {
    var list = addBtn.__list;
    if (!list) return;
    if (list.hasAttribute('data-cms-list-photo')) { addPhotos(list); return; }
    var p = list.getAttribute('data-cms-list').split('|');
    listOp(p[0], p[1], 'add', -1, list.getAttribute('data-cms-list-label') || 'item');
  });

  // Grouped lists (data-cms-list-group, e.g. gallery category): the group field and
  // the values in use, in page order.
  function listGroups(list) {
    var field = list.getAttribute('data-cms-list-group');
    if (!field) return null;
    var p = list.getAttribute('data-cms-list').split('|');
    var items = getPath(DOCS[p[0]] || {}, p[1]);
    var seen = {}, values = [];
    (Array.isArray(items) ? items : []).forEach(function (it) {
      var v = it && typeof it[field] === 'string' ? it[field].trim() : '';
      if (v && !seen[v]) { seen[v] = true; values.push(v); }
    });
    return { field: field, values: values };
  }
  function itemGroup(list, index) {
    var g = listGroups(list);
    if (!g) return '';
    var p = list.getAttribute('data-cms-list').split('|');
    var it = (getPath(DOCS[p[0]] || {}, p[1]) || [])[index];
    return it && typeof it[g.field] === 'string' ? it[g.field].trim() : '';
  }

  function promptBox(title, text, okLabel, placeholder, value) {
    return new Promise(function (resolve) {
      var close = function (v) { m.remove(); resolve(v); };
      var input = h('input', { type: 'search', placeholder: placeholder || '', onkeydown: function (e) {
        if (e.key === 'Enter') { e.preventDefault(); ok(); } else if (e.key === 'Escape') close(null);
      } });
      if (value) input.value = value;
      var ok = function () { var v = input.value.trim(); if (v) close(v); else input.focus(); };
      var m = h('div', { class: 'cms-modal', role: 'dialog', 'aria-modal': 'true', onclick: function (e) { if (e.target === m) close(null); } }, [
        h('div', { class: 'cms-modal-box is-small' }, [
          h('div', { class: 'cms-modal-head' }, [h('h3', { text: title })]),
          h('div', { class: 'cms-confirm-body' }, [h('p', { text: text, style: 'margin:0 0 10px' }), input]),
          h('div', { class: 'cms-confirm-foot' }, [
            h('button', { class: 'cms-btn', type: 'button', text: 'Cancel', onclick: function () { close(null); } }),
            h('button', { class: 'cms-btn cms-btn-primary', type: 'button', text: okLabel || 'OK', onclick: ok })
          ])
        ])
      ]);
      document.body.appendChild(m);
      input.focus();
    });
  }

  // Visible "Add photos" bar under every photo list (gallery projects, photo
  // sections…). Grouped lists get one button per group plus "New …".
  function buildPhotoAdder(list) {
    var label = list.getAttribute('data-cms-list-label') || 'photo';
    var g = listGroups(list);
    var btn = function (text, title, onclick, cls) {
      return h('button', { type: 'button', class: 'cms-btn cms-btn-sm' + (cls ? ' ' + cls : ''), title: title, html: ICON.photos + ' ' + esc(text), onclick: function (e) {
        e.preventDefault(); e.stopPropagation(); onclick();
      } });
    };
    var bar = h('div', { class: 'cms-photo-adder' });
    if (g) {
      var noun = g.field.replace(/_/g, ' ');
      bar.appendChild(h('span', { text: 'Add photos to:' }));
      g.values.forEach(function (v) {
        bar.appendChild(btn(v, 'Upload photos — each becomes a new ' + label + ' in ' + v, function () { addPhotos(list, v); }));
      });
      bar.appendChild(btn('New ' + noun + '…', 'Create a new ' + noun + ' (adds a filter button) and upload its photos', function () {
        promptBox('New ' + noun, 'Name it (e.g. "Margarine"). A filter button with this name appears once its photos are added.', 'Choose photos…', 'Name')
          .then(function (v) { if (v) addPhotos(list, v); });
      }, 'cms-btn-primary'));
    } else {
      bar.appendChild(btn('Add photos', 'Upload several photos — each becomes a new ' + label, function () { addPhotos(list); }, 'cms-btn-primary'));
      bar.appendChild(h('span', { class: 'cms-photo-adder-hint', text: 'Select several at once — each becomes a new ' + label + '.' }));
    }
    if (list.hasAttribute('data-cms-list-youtube')) {
      bar.appendChild(h('button', { type: 'button', class: 'cms-btn cms-btn-sm', title: 'Paste a YouTube link — it becomes a new ' + label + ' that plays in a pop-up', html: ICON.youtube + ' YouTube video…', onclick: function (e) {
        e.preventDefault(); e.stopPropagation(); addYoutube(list);
      } }));
    }
    list.parentNode.insertBefore(bar, list.nextSibling);
  }

  // YouTube link → video id ('' when it isn't one). Mirrors youtube_id() in app/lib/sanitize.php.
  function youtubeId(url) {
    url = String(url || '').trim();
    if (/^[A-Za-z0-9_-]{11}$/.test(url)) return url;
    var m = /^(?:https?:\/\/)?(?:www\.|m\.|music\.)?(?:youtube\.com|youtube-nocookie\.com|youtu\.be)\/(?:watch\?(?:.*&)?v=|embed\/|shorts\/|live\/|v\/)?([A-Za-z0-9_-]{11})(?:[?&#\/]|$)/i.exec(url);
    return m ? m[1] : '';
  }

  // Choose a group (e.g. gallery category) from a dropdown of the ones in use, plus
  // $suggest (when not in use yet) and "New …" which reveals a name box.
  // Resolves to the chosen name, or null when cancelled.
  function groupPicker(g, okLabel, suggest) {
    var noun = g.field.replace(/_/g, ' ');
    var NEW = '\u0000new';
    return new Promise(function (resolve) {
      var close = function (v) { m.remove(); resolve(v); };
      var sel = h('select', { 'aria-label': noun });
      var values = g.values.slice();
      if (suggest && values.indexOf(suggest) < 0) values.push(suggest);
      values.forEach(function (v) {
        sel.appendChild(h('option', { value: v, text: v + (g.values.indexOf(v) < 0 ? ' (new)' : '') }));
      });
      sel.appendChild(h('option', { value: NEW, text: '+ New ' + noun + '…' }));
      sel.value = suggest && values.indexOf(suggest) >= 0 ? suggest : values[0] || NEW;
      var input = h('input', { type: 'search', placeholder: 'Name of the new ' + noun, style: 'margin-top:10px', onkeydown: function (e) {
        if (e.key === 'Enter') { e.preventDefault(); ok(); } else if (e.key === 'Escape') close(null);
      } });
      var sync = function () { var on = sel.value === NEW; input.style.display = on ? '' : 'none'; if (on) input.focus(); };
      sel.addEventListener('change', sync);
      sel.addEventListener('keydown', function (e) { if (e.key === 'Escape') close(null); });
      var ok = function () {
        if (sel.value !== NEW) { close(sel.value); return; }
        var v = input.value.trim();
        if (v) close(v); else input.focus();
      };
      var m = h('div', { class: 'cms-modal', role: 'dialog', 'aria-modal': 'true', onclick: function (e) { if (e.target === m) close(null); } }, [
        h('div', { class: 'cms-modal-box is-small' }, [
          h('div', { class: 'cms-modal-head' }, [h('h3', { text: 'Which ' + noun + '?' })]),
          h('div', { class: 'cms-confirm-body' }, [h('p', { text: 'The video appears under this filter button. A new ' + noun + ' gets its own button.', style: 'margin:0 0 10px' }), sel, input]),
          h('div', { class: 'cms-confirm-foot' }, [
            h('button', { class: 'cms-btn', type: 'button', text: 'Cancel', onclick: function () { close(null); } }),
            h('button', { class: 'cms-btn cms-btn-primary', type: 'button', text: okLabel || 'OK', onclick: ok })
          ])
        ])
      ]);
      document.body.appendChild(m);
      sync();
      sel.focus();
    });
  }

  // One new list item per YouTube link (gallery projects). Grouped lists ask which
  // group (category) it belongs to unless it was added from an item of that group.
  function addYoutube(list, groupValue) {
    var field = list.getAttribute('data-cms-list-youtube');
    var p = list.getAttribute('data-cms-list').split('|');
    var label = list.getAttribute('data-cms-list-label') || 'item';
    var g = listGroups(list);
    var link = '';
    promptBox('Add a YouTube video', 'Paste the video link (e.g. https://www.youtube.com/watch?v=… or https://youtu.be/…). It becomes a new ' + label + ' that plays in a pop-up.', 'Next', 'https://www.youtube.com/watch?v=…')
      .then(function (v) {
        if (!v) return null;
        if (!youtubeId(v)) { toast('That is not a YouTube video link.', 'error'); return null; }
        link = v;
        if (!g || groupValue) return groupValue || '';
        return groupPicker(g, 'Add video', 'Videos');
      })
      .then(function (group) {
        if (group === null || !link) return null;
        // The video's own title when YouTube shares it (falls back to "New video").
        var title = window.fetch ? fetch('https://www.youtube.com/oembed?format=json&url=' + encodeURIComponent('https://www.youtube.com/watch?v=' + youtubeId(link)))
          .then(function (r) { return r.ok ? r.json() : {}; }).then(function (j) { return (j && j.title) || ''; }).catch(function () { return ''; }) : Promise.resolve('');
        return title.then(function (t) {
          return api('list', { doc: p[0], path: p[1], op: 'add_youtube', field: field, url: link, title: t,
            photo: list.getAttribute('data-cms-list-photo') || '', group: g && group ? { field: g.field, value: group } : null });
        }).then(function () {
          toast('Video added' + (group ? ' to ' + group : '') + ' — edit its text now', 'ok');
          setTimeout(reloadKeepingScroll, 600);
        });
      })
      .catch(function (err) { toast(err.message, 'error'); });
  }
  document.querySelectorAll('[data-cms-list-photo]').forEach(buildPhotoAdder);

  // Bulk photo upload: every photo becomes a new item (gallery projects, photo grids…)
  function addPhotos(list, groupValue) {
    var field = list.getAttribute('data-cms-list-photo');
    var p = list.getAttribute('data-cms-list').split('|');
    var groupField = list.getAttribute('data-cms-list-group');
    var group = groupField && groupValue ? { field: groupField, value: groupValue } : null;
    var input = h('input', { type: 'file', accept: 'image/*', multiple: true, style: 'display:none' });
    document.body.appendChild(input);
    input.addEventListener('change', function () {
      var files = Array.prototype.slice.call(input.files);
      input.remove();
      if (!files.length) return;
      var photos = [], i = 0;
      var next = function () {
        if (i >= files.length) {
          if (!photos.length) return null;
          return api('list', { doc: p[0], path: p[1], op: 'add_photos', field: field, photos: photos, group: group }).then(function () {
            toast(photos.length + ' photo' + (photos.length > 1 ? 's' : '') + ' added' + (group ? ' to ' + group.value : '') + ' (converted to WebP) — edit their text now', 'ok');
            setTimeout(reloadKeepingScroll, 600);
          }).catch(function (err) { toast(err.message, 'error'); });
        }
        var f = files[i++];
        toast('Uploading ' + i + ' of ' + files.length + '…');
        return upload(f).then(function (res) { photos.push({ url: res.url, name: niceName(f.name) }); })
          .catch(function (err) { toast(f.name + ': ' + err.message, 'error'); })
          .then(next);
      };
      next();
    });
    input.click();
  }

  // "+ Add a section here" → choose a section type
  document.addEventListener('click', function (e) {
    var btn = e.target.closest && e.target.closest('[data-cms-add-block]');
    if (!btn) return;
    e.preventDefault();
    var parts = btn.getAttribute('data-cms-add-block').split('|');
    var close = function () { m.remove(); };
    var types = CFG.blockTypes || {};
    var grid = h('div', { class: 'cms-blocktypes' }, Object.keys(types).map(function (type) {
      return h('button', { type: 'button', class: 'cms-blocktype', onclick: function () {
        close();
        api('list', { doc: parts[0], path: parts[1], op: 'add_block', type: type }).then(function () {
          toast(types[type].label + ' section added — hover it to edit', 'ok');
          setTimeout(reloadKeepingScroll, 400);
        }).catch(function (err) { toast(err.message, 'error'); });
      } }, [h('b', { text: types[type].label }), h('span', { text: types[type].hint })]);
    }));
    var m = h('div', { class: 'cms-modal', role: 'dialog', 'aria-modal': 'true', onclick: function (ev) { if (ev.target === m) close(); } }, [
      h('div', { class: 'cms-modal-box is-medium' }, [
        h('div', { class: 'cms-modal-head' }, [h('h3', { text: 'Add a section' }), h('button', { class: 'cms-x', type: 'button', 'aria-label': 'Close', text: '×', onclick: close })]),
        h('div', { class: 'cms-modal-body' }, [grid])
      ])
    ]);
    document.body.appendChild(m);
  });

  [pencil, itemBar, sectionBar, addBtn].forEach(function (n) {
    n.addEventListener('mouseenter', function () { overUi = true; clearTimeout(switchTimer); });
    n.addEventListener('mouseleave', function () { overUi = false; });
  });
  pencil.addEventListener('click', function (e) {
    e.preventDefault();
    if (hover.edit) openPanel(hover.edit);
  });

  document.addEventListener('mousemove', function (e) {
    mouse.x = e.clientX; mouse.y = e.clientY;
    if (!pending) { pending = true; requestAnimationFrame(pick); }
  }, { passive: true });
  window.addEventListener('scroll', function () { if (!pending) { pending = true; requestAnimationFrame(pick); } }, { passive: true });
  window.addEventListener('resize', function () { requestAnimationFrame(place); });
  document.addEventListener('mouseleave', function () {
    clearTimeout(switchTimer);
    hover = { edit: null, item: null, section: null, emptyList: null };
    place();
  });

  // Alt+click (or double-click on an image) opens the editor directly.
  document.addEventListener('click', function (e) {
    if (!e.altKey) return;
    var ed = e.target.closest && e.target.closest('[data-cms-edit]');
    if (ed && !e.target.closest('.cms-panel, .cms-modal, #cms-adminbar')) {
      e.preventDefault(); e.stopPropagation();
      openPanel(ed);
    }
  }, true);

  // -------------------------------------------------------------- side panel
  var panel = { el: null, open: false, target: null, spec: null, fields: [], dirty: false, originals: [] };

  function bindings(doc, path) {
    return document.querySelectorAll('[data-cms-b^="' + (doc + '|' + path + '|').replace(/"/g, '\\"') + '"]');
  }
  function applyBinding(doc, path, value) {
    bindings(doc, path).forEach(function (el) {
      var mode = el.getAttribute('data-cms-b').split('|')[2];
      if (mode === 'text') el.textContent = value === null || value === undefined ? '' : String(value);
      else if (mode === 'ml') el.innerHTML = esc(value).replace(/\n/g, '<br>');
      else if (mode === 'html' || mode === 'rawhtml') el.innerHTML = value || '';
      else if (mode === 'css') el.textContent = scopeCss(String(value || ''), el.getAttribute('data-cms-scope') || '');
      else if (mode === 'img') {
        var v = imgVal(value);
        el = swapMediaTag(el, isVideoSrc(v.src));
        el.src = resolveUrl(v.src);
        if (el.tagName === 'VIDEO') el.play().catch(function () {});
        if (v.alt) el.tagName === 'VIDEO' ? el.setAttribute('aria-label', v.alt) : (el.alt = v.alt);
        applyFraming(el, value);
      } else if (mode === 'video') {
        var vs = resolveUrl(imgVal(value).src);
        var source = el.querySelector('source');
        if (source && source.getAttribute('src') !== vs) { source.src = vs; el.load(); }
        applyFraming(el, value);
      }
    });
  }
  function isVideoSrc(src) { return /\.(mp4|webm)([?#]|$)/i.test(src || ''); }
  function applyFraming(el, value) {
    var v = value && typeof value === 'object' ? value : {};
    el.style.objectFit = v.fit || '';
    el.style.objectPosition = v.pos || '';
  }
  // An image spot that now holds a video (or back): replace the element in place.
  function swapMediaTag(el, video) {
    if ((el.tagName === 'VIDEO') === video) return el;
    var n = document.createElement(video ? 'video' : 'img');
    ['class', 'style', 'data-cms-edit', 'data-cms-b', 'width', 'height'].forEach(function (a) {
      if (el.hasAttribute(a)) n.setAttribute(a, el.getAttribute(a));
    });
    if (video) { n.muted = n.autoplay = n.loop = n.playsInline = true; n.setAttribute('muted', ''); n.setAttribute('playsinline', ''); }
    el.replaceWith(n);
    if (panel.target === el) panel.target = n;
    if (hover.edit === el) hover.edit = n;
    return n;
  }

  function ensurePanel() {
    if (panel.el) return panel.el;
    var el = h('aside', { class: 'cms-panel', role: 'dialog', 'aria-label': 'Edit content' });
    el.innerHTML = '<div class="cms-panel-head"><h3></h3><button type="button" class="cms-x" aria-label="Close">×</button></div>' +
      '<div class="cms-panel-body"></div>' +
      '<div class="cms-panel-foot"><span class="cms-status"></span><button type="button" class="cms-btn" data-act="cancel">Cancel</button><button type="button" class="cms-btn cms-btn-primary cms-btn-lg" data-act="save">Save</button></div>';
    el.querySelector('.cms-x').addEventListener('click', function () { closePanel(); });
    el.querySelector('[data-act="cancel"]').addEventListener('click', function () { closePanel(true); });
    el.querySelector('[data-act="save"]').addEventListener('click', savePanel);
    el.addEventListener('keydown', function (e) {
      if ((e.ctrlKey || e.metaKey) && e.key === 's') { e.preventDefault(); savePanel(); }
    });
    document.body.appendChild(el);
    panel.el = el;
    return el;
  }

  function openPanel(target, specOverride) {
    var spec = specOverride || specOf(target);
    if (!spec) return;
    var proceed = function () {
      if (panel.target) panel.target.classList.remove('cms-selected');
      var el = ensurePanel();
      panel.target = target;
      panel.spec = spec;
      panel.dirty = false;
      panel.fields = [];
      panel.originals = [];
      target && target.classList.add('cms-selected');
      var title = specName(spec);
      el.querySelector('h3').innerHTML = esc(title) + '<small>Changes are saved as a draft until you Publish</small>';
      var body = el.querySelector('.cms-panel-body');
      body.innerHTML = '';
      spec.f.forEach(function (f) {
        if (f.group) { body.appendChild(h('div', { class: 'cms-group-title', text: f.group })); return; }
        var doc = f.d || spec.d;
        var value = getPath(DOCS[doc] || {}, f.p);
        panel.originals.push({ doc: doc, path: f.p, value: value });
        var field = buildField(f, value, doc);
        panel.fields.push(field);
        body.appendChild(field.el);
      });
      el.querySelector('.cms-status').textContent = '';
      requestAnimationFrame(function () { el.classList.add('is-open'); });
      panel.open = true;
      setTimeout(function () {
        var first = body.querySelector('input:not([type=file]):not([type=checkbox]), textarea, .cms-rich');
        first && first.focus();
      }, 250);
    };
    if (panel.open && panel.dirty) {
      confirmBox('Discard unsaved changes?', 'You have edits in the panel that are not saved yet.', 'Discard', true).then(function (ok) {
        if (ok) { revertPreview(); proceed(); }
      });
    } else proceed();
  }

  function revertPreview() {
    panel.originals.forEach(function (o) { applyBinding(o.doc, o.path, o.value); });
  }

  function closePanel(revert) {
    if (!panel.el || !panel.open) return;
    var doClose = function () {
      if (revert !== false) revertPreview();
      panel.el.classList.remove('is-open');
      panel.open = false;
      panel.dirty = false;
      if (panel.target) panel.target.classList.remove('cms-selected');
      panel.target = null;
    };
    if (panel.dirty) {
      confirmBox('Close without saving?', 'Your changes in this panel will be lost.', 'Close without saving', true).then(function (ok) { if (ok) doClose(); });
    } else doClose();
  }

  function markDirty() {
    panel.dirty = true;
    panel.el.querySelector('.cms-status').textContent = 'Unsaved changes';
  }

  function savePanel() {
    if (!panel.open) return;
    var btn = panel.el.querySelector('[data-act="save"]');
    var byDoc = {};
    panel.fields.forEach(function (fld) {
      (byDoc[fld.doc] = byDoc[fld.doc] || []).push({ p: fld.def.p, t: fld.def.t, v: fld.get() });
    });
    btn.disabled = true;
    panel.el.querySelector('.cms-status').textContent = 'Saving…';
    var needsReload = false;
    var docs = Object.keys(byDoc);
    var chain = Promise.resolve();
    docs.forEach(function (doc) {
      chain = chain.then(function () {
        return api('save', { doc: doc, fields: byDoc[doc] }).then(function (res) {
          Object.keys(res.values || {}).forEach(function (path) {
            var v = res.values[path];
            DOCS[doc] = DOCS[doc] || {};
            setPath(DOCS[doc], path, v);
            var t = (byDoc[doc].filter(function (f) { return f.p === path; })[0] || {}).t;
            if (!LIVE_TYPES[t] || !bindings(doc, path).length) needsReload = true;
            else applyBinding(doc, path, v);
          });
        });
      });
    });
    chain.then(function () {
      btn.disabled = false;
      panel.dirty = false;
      panel.originals = [];
      closePanel(false);
      toast('Saved as draft — press Publish to go live', 'ok');
      if (needsReload) setTimeout(reloadKeepingScroll, 500);
    }).catch(function (err) {
      btn.disabled = false;
      panel.el.querySelector('.cms-status').textContent = '';
      toast(err.message, 'error');
    });
  }

  // ---------------------------------------------------------------- fields
  function buildField(def, value, doc) {
    var wrap = h('div', { class: 'cms-field' });
    var label = h('label', { class: 'cms-flabel', text: def.l || def.p });
    var get;
    var preview = function (v) { applyBinding(doc, def.p, v); markDirty(); };
    var t = def.t;

    if (t === 'text' || t === 'url' || t === 'number') {
      var input = h('input', { type: t === 'number' ? 'number' : 'text', value: value === undefined || value === null ? '' : (typeof value === 'object' ? value.src || '' : value), step: 'any', placeholder: def.ph || null });
      if (t === 'url') {
        var listId = 'cms-pages-list';
        if (!document.getElementById(listId)) {
          document.body.appendChild(h('datalist', { id: listId }, (CFG.pages || []).map(function (p) { return h('option', { value: p[0], label: p[1] }); })));
        }
        input.setAttribute('list', listId);
        input.setAttribute('spellcheck', 'false');
      }
      input.addEventListener('input', function () { preview(input.value); });
      wrap.appendChild(label);
      if (t === 'url') wrap.appendChild(linkPicker(input, function (v) { preview(v); }));
      wrap.appendChild(input);
      if (t === 'url') wrap.appendChild(h('p', { class: 'cms-hint', html: 'Pick from the list, or type a page (<code>/contact/</code>), web address (<code>https://…</code>), section (<code>#name</code>), <code>tel:</code> / <code>mailto:</code> link, or <code>#popup-name</code> to open a popup. Links to other websites open in a new tab.' }));
      get = function () { return input.value; };
    } else if (t === 'textarea' || t === 'lines') {
      var ta = h('textarea', { rows: t === 'lines' ? 7 : 5, placeholder: def.ph || null });
      ta.value = t === 'lines' ? (Array.isArray(value) ? value.join('\n') : (value || '')) : (value || '');
      ta.addEventListener('input', function () { preview(t === 'lines' ? ta.value.split('\n') : ta.value); });
      wrap.appendChild(label);
      wrap.appendChild(ta);
      if (t === 'lines') wrap.appendChild(h('p', { class: 'cms-hint', text: 'One item per line. Empty lines are ignored.' }));
      get = function () { return t === 'lines' ? ta.value.split('\n') : ta.value; };
    } else if (t === 'rich') {
      var area = h('div', { class: 'cms-rich', contenteditable: 'true', html: value || '' });
      var cmd = function (c, arg) { area.focus(); document.execCommand(c, false, arg); preview(area.innerHTML); };
      var rb = h('div', { class: 'cms-richbar' }, [
        h('button', { type: 'button', html: '<b>B</b>', title: 'Bold (Ctrl+B)', onclick: function () { cmd('bold'); } }),
        h('button', { type: 'button', html: '<i>I</i>', title: 'Italic (Ctrl+I)', onclick: function () { cmd('italic'); } }),
        h('button', { type: 'button', html: '<u>U</u>', title: 'Underline', onclick: function () { cmd('underline'); } }),
        h('button', { type: 'button', text: '• List', title: 'Bullet list', onclick: function () { cmd('insertUnorderedList'); } }),
        h('button', { type: 'button', text: '🔗 Link', title: 'Add link to selected text', onclick: function () {
          var url = prompt('Link address (https://…, /contact/, tel:, mailto:)', 'https://');
          if (url) cmd('createLink', url);
        } }),
        h('button', { type: 'button', text: 'Unlink', onclick: function () { cmd('unlink'); } }),
        h('button', { type: 'button', text: 'Clear style', title: 'Remove formatting from selection', onclick: function () { cmd('removeFormat'); } })
      ]);
      area.addEventListener('input', function () { preview(area.innerHTML); });
      area.addEventListener('paste', function (e) {
        e.preventDefault();
        var text = (e.clipboardData || window.clipboardData).getData('text/plain');
        document.execCommand('insertText', false, text);
      });
      wrap.appendChild(label);
      wrap.appendChild(rb);
      wrap.appendChild(area);
      wrap.appendChild(h('p', { class: 'cms-hint', text: 'Select text and use the buttons to format it. Pasted text is inserted without formatting.' }));
      get = function () { return area.innerHTML; };
    } else if (t === 'html' || t === 'css') {
      var code = h('textarea', { class: 'cms-code', rows: t === 'html' ? 16 : 10, spellcheck: 'false', wrap: 'off' });
      code.value = value || '';
      code.addEventListener('input', function () { preview(code.value); });
      code.addEventListener('keydown', function (e) {
        if (e.key !== 'Tab') return;
        e.preventDefault();
        var st = code.selectionStart, en = code.selectionEnd;
        code.value = code.value.slice(0, st) + '  ' + code.value.slice(en);
        code.selectionStart = code.selectionEnd = st + 2;
        preview(code.value);
      });
      wrap.appendChild(h('div', { class: 'cms-code-head' }, [label,
        h('button', { type: 'button', class: 'cms-btn cms-btn-sm', text: '⤢ Wide editor', onclick: function () { panel.el.classList.toggle('is-wide'); } })]));
      wrap.appendChild(code);
      wrap.appendChild(h('p', { class: 'cms-hint', html: t === 'html'
        ? 'Any HTML. Changes preview live. A link to <code>#popup-name</code> opens that popup; add <code>data-popup-close</code> to a button to close one. Scripts are removed for safety. Website classes (e.g. <code>rounded-2xl bg-sky-500 text-white p-6</code>) work, or style it in the CSS box.'
        : 'Normal CSS — it only affects this section/popup. Example: <code>.card { padding: 24px; border-radius: 16px; }</code>' }));
      get = function () { return code.value; };
    } else if (t === 'bool') {
      var cb = h('input', { type: 'checkbox' });
      cb.checked = value === undefined || value === null ? true : !!value;
      cb.addEventListener('change', markDirty);
      wrap.appendChild(h('label', { class: 'cms-switch' }, [cb, h('i'), h('span', { text: def.l })]));
      get = function () { return cb.checked; };
    } else if (t === 'select') {
      var sel = h('select');
      (def.o || []).forEach(function (o) {
        var v = Array.isArray(o) ? o[0] : o;
        var lbl = Array.isArray(o) ? o[1] : o;
        sel.appendChild(h('option', { value: v, text: lbl }));
      });
      sel.value = value === undefined || value === null ? '' : value;
      // Nothing stored (or an unknown value): show the default the page actually uses.
      if (sel.selectedIndex < 0 || sel.value !== String(value === undefined || value === null ? '' : value)) {
        sel.value = def.dv !== undefined && def.dv !== null ? def.dv : '';
      }
      sel.addEventListener('change', markDirty);
      wrap.appendChild(label);
      wrap.appendChild(sel);
      get = function () { return sel.value; };
    } else if (t === 'icon') {
      var current = value || '';
      var grid = h('div', { class: 'cms-icons' });
      Object.keys(CFG.icons || {}).forEach(function (name) {
        var b = h('button', { type: 'button', title: name, html: CFG.icons[name], class: name === current ? 'is-on' : '', onclick: function () {
          current = name;
          grid.querySelectorAll('button').forEach(function (x) { x.classList.toggle('is-on', x === b); });
          markDirty();
        } });
        grid.appendChild(b);
      });
      wrap.appendChild(label);
      wrap.appendChild(grid);
      get = function () { return current; };
    } else if (t === 'color') {
      var c = h('input', { type: 'color', value: value || '#0ea5e9' });
      c.addEventListener('input', markDirty);
      wrap.appendChild(label);
      wrap.appendChild(c);
      get = function () { return c.value; };
    } else if (t === 'image' || t === 'video') {
      var res = buildMediaField(def, value, t, preview);
      wrap.appendChild(label);
      wrap.appendChild(res.el);
      get = res.get;
    } else {
      var other = h('input', { type: 'text', value: value || '' });
      other.addEventListener('input', function () { preview(other.value); });
      wrap.appendChild(label);
      wrap.appendChild(other);
      get = function () { return other.value; };
    }
    return { el: wrap, def: def, doc: doc, get: get };
  }

  function linkPicker(input, onPick) {
    var pick = h('select', { class: 'cms-linkpick', 'aria-label': 'Choose a link' });
    pick.appendChild(h('option', { value: '', text: '↳ Choose: page, section, popup, phone, e-mail…' }));
    var group = function (label, items) {
      if (!items.length) return;
      var g = h('optgroup', { label: label });
      items.forEach(function (it) { g.appendChild(h('option', { value: it[0], text: it[1] })); });
      pick.appendChild(g);
    };
    group('Pages', (CFG.pages || []).map(function (p) { return [p[0], p[1]]; }));
    group('Sections on this page', Array.prototype.slice.call(document.querySelectorAll('main section[id], main [data-blk][id]'))
      .map(function (el) { return ['#' + el.id, '#' + el.id]; }));
    group('Open a popup', (CFG.popups || []).map(function (p) { return ['#popup-' + p.id, 'Popup: ' + (p.title || p.id)]; }));
    var c = (DOCS.site && DOCS.site.contact) || {};
    var contact = [];
    if (c.phone_href) contact.push([c.phone_href, 'Call ' + (c.phone_display || '')]);
    if (c.email_href) contact.push([c.email_href, 'E-mail ' + (c.email_display || '')]);
    if (c.whatsapp_number) contact.push(['https://wa.me/' + String(c.whatsapp_number).replace(/\D/g, ''), 'WhatsApp chat']);
    group('Contact', contact);
    pick.addEventListener('change', function () {
      if (!pick.value) return;
      input.value = pick.value;
      onPick(pick.value);
      pick.value = '';
    });
    return pick;
  }

  function buildMediaField(def, value, kind, preview) {
    var isVideo = kind === 'video';
    var cur = isVideo ? { src: (value && value.src) || value || '', alt: '' } : imgVal(value);
    cur.fit = (value && value.fit) || '';
    cur.pos = (value && value.pos) || '';
    var box = h('div', { class: 'cms-img' });
    var pv = h('div', { class: 'cms-img-preview' });
    var progress = h('div', { class: 'cms-progress' }, [h('i')]);
    var meta = h('div', { class: 'cms-img-meta' });
    var urlInput = h('input', { type: 'text', value: cur.src, spellcheck: 'false' });
    var altInput = isVideo ? null : h('input', { type: 'text', value: cur.alt, placeholder: 'Describe the image (helps Google & screen readers)' });
    // Field options (def.o): removable → "Remove" button; imageOnly → no video for this spot.
    var opts = def.o && typeof def.o === 'object' && !Array.isArray(def.o) ? def.o : {};
    // Image spots also take a video (it plays silently on a loop in place of the image).
    var file = h('input', { type: 'file', accept: isVideo ? 'video/mp4,video/webm' : (opts.imageOnly ? 'image/*' : 'image/*,video/mp4,video/webm'), style: 'display:none' });

    var value_ = function () {
      var framing = {};
      if (cur.fit) framing.fit = cur.fit;
      if (cur.pos) framing.pos = cur.pos;
      if (isVideo) return framing.fit || framing.pos ? Object.assign({ src: cur.src }, framing) : cur.src;
      return Object.assign({ src: cur.src, alt: altInput ? altInput.value : '' }, framing);
    };
    var render = function () {
      pv.innerHTML = '';
      if (cur.src) {
        var m = isVideoSrc(cur.src) ? h('video', { src: resolveUrl(cur.src), muted: true, controls: true, preload: 'metadata' }) : h('img', { src: resolveUrl(cur.src), alt: '' });
        pv.appendChild(m);
      } else {
        pv.appendChild(h('span', { class: 'cms-hint', text: 'No ' + kind + ' selected' }));
      }
      meta.textContent = cur.src ? cur.src.split('/').pop() : '';
    };
    var set = function (src) {
      cur.src = src;
      urlInput.value = src;
      render();
      preview(value_());
    };
    var doUpload = function (f) {
      if (!f) return;
      progress.style.display = 'block';
      progress.firstChild.style.width = '5%';
      upload(f, function (p) { progress.firstChild.style.width = Math.round(p * 100) + '%'; })
        .then(function (res) { set(res.url); toast(uploadSummary(res), 'ok'); })
        .catch(function (err) { toast(err.message, 'error'); })
        .then(function () { progress.style.display = 'none'; file.value = ''; });
    };
    file.addEventListener('change', function () { doUpload(file.files[0]); });
    ['dragenter', 'dragover'].forEach(function (ev) { pv.addEventListener(ev, function (e) { e.preventDefault(); pv.classList.add('is-drag'); }); });
    ['dragleave', 'drop'].forEach(function (ev) { pv.addEventListener(ev, function (e) { e.preventDefault(); pv.classList.remove('is-drag'); }); });
    pv.addEventListener('drop', function (e) { if (e.dataTransfer.files[0]) doUpload(e.dataTransfer.files[0]); });
    urlInput.addEventListener('change', function () { set(urlInput.value.trim()); });
    altInput && altInput.addEventListener('input', function () { preview(value_()); });

    box.appendChild(pv);
    box.appendChild(progress);
    var actions = [
      h('button', { type: 'button', class: 'cms-btn cms-btn-primary', text: '⬆ Upload new', title: isVideo ? 'Upload a video (MP4 / WebM)' : 'Upload an image or a video', onclick: function () { file.click(); } }),
      h('button', { type: 'button', class: 'cms-btn', text: '▦ Choose from library', onclick: function () { openLibrary(isVideo ? 'video' : 'image').then(function (u) { if (u) set(u); }); } })
    ];
    if (!isVideo && !opts.imageOnly) {
      actions.push(h('button', { type: 'button', class: 'cms-btn', text: '▶ Use a video', title: 'Show a video here instead of the image (plays silently on a loop)', onclick: function () {
        openLibrary('video').then(function (u) { if (u) set(u); });
      } }));
    }
    if (opts.removable) {
      actions.push(h('button', { type: 'button', class: 'cms-btn', text: '✕ Remove image', title: 'Show no image here', onclick: function () { set(''); } }));
    }
    actions.push(file);
    box.appendChild(h('div', { class: 'cms-img-actions' }, actions));
    box.appendChild(meta);
    render();

    // Framing: how the picture fills its frame, and which part stays visible.
    var reframe = function () { render(); preview(value_()); };
    var fitRow = h('div', { class: 'cms-seg' });
    [['', 'Default'], ['cover', 'Fill (crop)'], ['contain', 'Fit (whole)'], ['fill', 'Stretch'], ['none', 'Original size']].forEach(function (o) {
      fitRow.appendChild(h('button', { type: 'button', text: o[1], 'data-v': o[0], class: cur.fit === o[0] ? 'is-on' : '', onclick: function () {
        cur.fit = o[0];
        fitRow.querySelectorAll('button').forEach(function (b) { b.classList.toggle('is-on', b.getAttribute('data-v') === cur.fit); });
        reframe();
      } }));
    });
    var posGrid = h('div', { class: 'cms-posgrid' });
    [['left top', '↖'], ['top', '↑'], ['right top', '↗'], ['left', '←'], ['center', '•'], ['right', '→'], ['left bottom', '↙'], ['bottom', '↓'], ['right bottom', '↘']].forEach(function (o) {
      posGrid.appendChild(h('button', { type: 'button', text: o[1], title: 'Align ' + o[0], 'data-v': o[0], class: cur.pos === o[0] ? 'is-on' : '', onclick: function () {
        cur.pos = cur.pos === o[0] ? '' : o[0];
        posGrid.querySelectorAll('button').forEach(function (b) { b.classList.toggle('is-on', b.getAttribute('data-v') === cur.pos); });
        reframe();
      } }));
    });

    var wrap = h('div', null, [box]);
    wrap.appendChild(h('div', { class: 'cms-field', style: 'margin-top:12px' }, [
      h('label', { class: 'cms-flabel', text: 'Size in its frame' }), fitRow,
      h('p', { class: 'cms-hint', text: 'Fill crops the edges to cover the whole space · Fit shows the whole picture (may leave empty bands) · Stretch distorts to fit.' })
    ]));
    wrap.appendChild(h('div', { class: 'cms-field' }, [
      h('label', { class: 'cms-flabel', text: 'Alignment' }),
      h('div', { class: 'cms-posrow' }, [posGrid, h('p', { class: 'cms-hint', text: 'Which part stays in view when the picture is cropped or smaller than its frame: top, center, bottom, left, right or a corner. Click again to reset.' })])
    ]));
    if (altInput) {
      wrap.appendChild(h('div', { class: 'cms-field' }, [h('label', { class: 'cms-flabel', text: 'Alt text' }), altInput]));
    }
    wrap.appendChild(h('details', { style: 'margin-top:8px' }, [
      h('summary', { class: 'cms-hint', style: 'cursor:pointer', text: 'Advanced: file address' }),
      urlInput
    ]));
    wrap.appendChild(h('p', { class: 'cms-hint', text: 'Tip: drag a file onto the preview to upload' + (isVideo ? '' : ' — an image or an MP4 / WebM video') + '. Images are converted to compressed WebP automatically. Max ' + (CFG.uploadMax || '') + '.' }));
    return { el: wrap, get: value_ };
  }

  // ------------------------------------------------------------ media library
  var mediaCache = null;
  function openLibrary(kind) {
    return new Promise(function (resolve) {
      var tab = 'uploads';
      var query = '';
      var close = function (v) { m.remove(); document.removeEventListener('keydown', onKey); resolve(v || null); };
      var onKey = function (e) { if (e.key === 'Escape') close(null); };
      document.addEventListener('keydown', onKey);
      var body = h('div', { class: 'cms-modal-body' }, [h('div', { class: 'cms-empty', text: 'Loading…' })]);
      var tabs = h('div', { class: 'cms-modal-tabs' });
      var search = h('input', { type: 'search', placeholder: 'Search by file name…' });
      var file = h('input', { type: 'file', accept: kind === 'video' ? 'video/mp4,video/webm' : 'image/*', multiple: true, style: 'display:none' });
      var draw = function () {
        tabs.innerHTML = '';
        [['uploads', 'Your uploads'], ['bundled', 'Website images']].forEach(function (t) {
          tabs.appendChild(h('button', { type: 'button', class: tab === t[0] ? 'is-on' : '', text: t[1], onclick: function () { tab = t[0]; draw(); } }));
        });
        var items = (mediaCache && mediaCache[tab]) || [];
        items = items.filter(function (it) {
          var isVid = (it.mime || '').indexOf('video/') === 0;
          var isImg = (it.mime || '').indexOf('image/') === 0;
          if (kind === 'video' ? !isVid : !isImg) return false;
          return !query || (it.name + ' ' + it.url).toLowerCase().indexOf(query) !== -1;
        });
        body.innerHTML = '';
        if (!mediaCache) { body.appendChild(h('div', { class: 'cms-empty', text: 'Loading…' })); return; }
        if (!items.length) { body.appendChild(h('div', { class: 'cms-empty', text: tab === 'uploads' ? 'No uploads yet — use “Upload” above.' : 'Nothing found.' })); return; }
        body.appendChild(h('div', { class: 'cms-grid' }, items.map(function (it) {
          var src = resolveUrl(it.url);
          return h('button', { type: 'button', class: 'cms-tile', title: it.url, onclick: function () { close(it.url); } }, [
            h('div', { class: 'cms-tile-img' }, [kind === 'video' ? h('video', { src: src, muted: true, preload: 'metadata' }) : h('img', { src: src, alt: '', loading: 'lazy' })]),
            h('span', { text: it.name })
          ]);
        })));
      };
      file.addEventListener('change', function () {
        var files = Array.prototype.slice.call(file.files);
        if (!files.length) return;
        body.innerHTML = '<div class="cms-empty">Uploading ' + files.length + ' file(s)…</div>';
        var chain = Promise.resolve(), last = null;
        files.forEach(function (f) { chain = chain.then(function () { return upload(f).then(function (r) { last = r; }); }); });
        chain.then(function () {
          toast(files.length === 1 && last ? uploadSummary(last) : 'Uploaded ' + files.length + ' files — converted to WebP', 'ok');
          if (files.length === 1 && last) { close(last.url); return; }
          return api('media', {}).then(function (res) { mediaCache = res; tab = 'uploads'; draw(); });
        }).catch(function (err) { toast(err.message, 'error'); draw(); });
      });
      search.addEventListener('input', function () { query = search.value.trim().toLowerCase(); draw(); });
      var m = h('div', { class: 'cms-modal', role: 'dialog', 'aria-modal': 'true', onclick: function (e) { if (e.target === m) close(null); } }, [
        h('div', { class: 'cms-modal-box' }, [
          h('div', { class: 'cms-modal-head' }, [
            h('h3', { text: kind === 'video' ? 'Choose a video' : 'Choose an image' }),
            h('button', { type: 'button', class: 'cms-btn cms-btn-primary', text: '⬆ Upload', onclick: function () { file.click(); } }),
            h('button', { type: 'button', class: 'cms-x', 'aria-label': 'Close', text: '×', onclick: function () { close(null); } }),
            file
          ]),
          tabs,
          h('div', { class: 'cms-modal-tools' }, [search]),
          body
        ])
      ]);
      document.body.appendChild(m);
      search.focus();
      if (mediaCache) draw();
      else api('media', {}).then(function (res) { mediaCache = res; if (!res.uploads.filter(function (x) { return (x.mime || '').indexOf(kind) === 0; }).length) tab = 'bundled'; draw(); })
        .catch(function (err) { body.innerHTML = ''; body.appendChild(h('div', { class: 'cms-empty', text: err.message })); });
      draw();
    });
  }

  // ------------------------------------------------------------- page settings
  function openSeoPanel() {
    var doc = CFG.page.doc;
    if (!doc) { toast('This page has no settings.', 'error'); return; }
    var base = CFG.page.seo || 'seo';
    var fields = [
      { p: base + '.title', t: 'text', l: 'Page title (browser tab & Google)', d: doc, ph: document.title },
      { p: base + '.description', t: 'textarea', l: 'Meta description (Google snippet, ~155 characters)', d: doc,
        ph: (document.querySelector('meta[name="description"]') || {}).content || '' },
      { p: base + '.keywords', t: 'textarea', l: 'Keywords for this page (comma separated, most important first)', d: doc,
        ph: 'e.g. edible oil refinery plant, solvent extraction plant' },
      { p: base + '.image', t: 'image', l: 'Share image (WhatsApp / LinkedIn preview)', d: doc },
      { group: 'Whole website' },
      { p: 'seo.title', t: 'text', l: 'Home page / default title', d: 'site' },
      { p: 'seo.title_suffix', t: 'text', l: 'Added after every page title', d: 'site' },
      { p: 'seo.description', t: 'textarea', l: 'Default description', d: 'site' },
      { p: 'seo.keywords', t: 'textarea', l: 'Keywords for every page (comma separated)', d: 'site' },
      { p: 'seo.og_image', t: 'image', l: 'Default share image', d: 'site' },
      { p: 'seo.og_image_alt', t: 'text', l: 'Share image description (alt text)', d: 'site' },
      { group: 'Local business (Google Maps & local search)' },
      { p: 'seo.geo_placename', t: 'text', l: 'City shown to search engines', d: 'site' },
      { p: 'seo.geo_position', t: 'text', l: 'Office position "latitude;longitude" (Google Maps → right-click the pin)', d: 'site' },
      { p: 'seo.opening_hours', t: 'text', l: 'Opening hours, e.g. Mo-Sa 09:00-18:00', d: 'site' },
      { p: 'seo.area_served', t: 'text', l: 'Countries served (comma separated)', d: 'site' },
      { p: 'seo.founding_year', t: 'text', l: 'Year founded', d: 'site' }
    ];
    if (!DOCS.site) DOCS.site = {};
    openPanel(null, { d: doc, n: 'Page settings (SEO)', f: fields });
  }

  // --------------------------------------------------------------- guards & tip
  window.addEventListener('beforeunload', function (e) {
    if (panel.open && panel.dirty) { e.preventDefault(); e.returnValue = ''; }
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && panel.open && !document.querySelector('.cms-modal')) closePanel();
  });

  try {
    if (!localStorage.getItem('cms-tip-seen')) {
      var tip = h('div', { class: 'cms-tip', role: 'note' }, [
        h('b', { text: 'You are editing the website' }),
        h('p', { html: 'Hover over any text, image or button and click the <span class="cms-pencil-demo">✎</span> pencil. Cards and lists show buttons to <b>move, copy or delete</b>. Sections can be hidden.' }),
        h('p', { html: 'Saved edits are <b>drafts</b> — visitors see them only after you press <b>Publish</b>.' }),
        h('button', { type: 'button', class: 'cms-btn cms-btn-primary', text: 'Got it', onclick: function () { tip.remove(); try { localStorage.setItem('cms-tip-seen', '1'); } catch (e) {} } })
      ]);
      document.body.appendChild(tip);
    }
  } catch (e) {}

  setPending(CFG.pending || 0);
})();
